(() => {
'use strict';
const root=document.querySelector('[data-watch-desk]');if(!root)return;
const en=(document.documentElement.lang||'tr').toLowerCase().startsWith('en');
const T=en?{empty:'No videos in this view yet.',watch:'Watch',open:'Open on Instagram',more:'Read more',less:'Show less',close:'Close',read:'Read with this video'}:{empty:'Bu görünümde henüz video yok.',watch:'İzle',open:'Instagram’da Aç',more:'Devamını oku',less:'Daralt',close:'Kapat',read:'Bu videoyla birlikte oku'};
const list=root.querySelector('[data-watch-list]'),tabs=[...root.querySelectorAll('[data-watch-filter]')];let data=[];
const esc=s=>String(s||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const ytId=u=>(String(u||'').match(/(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|embed\/|shorts\/))([\w-]{6,})/i)||[])[1]||'';
const igCode=u=>(String(u||'').match(/instagram\.com\/(?:reel|p)\/([^/?#]+)/i)||[])[1]||'';
function ratio(item){const f=String(item.format||'auto').toLowerCase();if(f.includes('9:16')||f.includes('dikey')||f==='vertical')return'vertical';if(f.includes('1:1')||f.includes('kare')||f==='square')return'square';if(f.includes('16:9')||f.includes('yatay')||f==='horizontal')return'horizontal';if(String(item.platform).toLowerCase()==='instagram'||/shorts\//i.test(item.url||''))return'vertical';return'horizontal'}
function poster(item){if(item.thumbnail)return item.thumbnail;const id=ytId(item.url);return id?`https://i.ytimg.com/vi/${id}/hqdefault.jpg`:''}
function openViewer(item){document.querySelector('.wd282-viewer')?.remove();const yt=String(item.platform).toLowerCase()==='youtube',r=ratio(item),id=yt?ytId(item.url):igCode(item.url);if(!id)return;const modal=document.createElement('div');modal.className=`wd282-viewer is-${r} ${yt?'is-youtube':'is-instagram'}`;modal.innerHTML=`<div class="wd282-viewer__shade"></div><section class="wd282-viewer__dialog"><button class="wd282-viewer__close" type="button" aria-label="${T.close}">×</button><div class="wd282-viewer__player">${yt?`<iframe src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(id)}?autoplay=1&rel=0" title="YouTube video" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe>`:`<iframe src="https://www.instagram.com/reel/${encodeURIComponent(id)}/embed/captioned/" title="Instagram Reel" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen scrolling="no"></iframe>`}</div><aside><small>${yt?'YOUTUBE':'INSTAGRAM'} / ${r.toUpperCase()} · ${esc(item.date||'')}</small><h2></h2><p></p><button class="wd282-more" type="button">${T.more}</button><div class="wd282-tags">${(item.tags||[]).map(x=>`<span>${esc(x)}</span>`).join('')}</div>${!yt?`<a href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">${T.open} ↗</a>`:''}</aside></section>`;modal.querySelector('h2').textContent=item.title;modal.querySelector('aside p').textContent=item.summary||'';document.body.appendChild(modal);document.body.classList.add('wd282-lock');const close=()=>{modal.remove();document.body.classList.remove('wd282-lock')};modal.querySelector('.wd282-viewer__close').onclick=close;modal.querySelector('.wd282-viewer__shade').onclick=close;modal.querySelector('.wd282-more').onclick=e=>{const open=modal.classList.toggle('show-all');e.currentTarget.textContent=open?T.less:T.more};document.addEventListener('keydown',function key(e){if(e.key==='Escape'){close();document.removeEventListener('keydown',key)}})}
function card(item,index){const yt=String(item.platform).toLowerCase()==='youtube',r=ratio(item),related=(item.related_publications||[])[0];return `<article class="wd282-card is-${r} ${yt?'is-youtube':'is-instagram'}"><button class="wd282-card__visual" type="button" data-index="${index}" aria-label="${esc(T.watch)}: ${esc(item.title)}"><div>${yt&&poster(item)?`<img src="${esc(poster(item))}" alt="" loading="lazy">`:`<span><small>${yt?'YOUTUBE':'REEL'} / ${String(index+1).padStart(2,'0')}</small><b>GERÇEĞİN<br>GERÇEĞİ</b></span>`}<i>▶</i></div></button><div class="wd282-card__copy"><small>${yt?'YOUTUBE':'INSTAGRAM'} / ${r.toUpperCase()} · ${esc(item.date||'')}</small><h2>${esc(item.title)}</h2><p>${esc(item.summary||'')}</p><footer><button type="button" data-index="${index}">${T.watch} →</button>${related?`<a href="/yayinlar/${encodeURIComponent(related)}.html">${T.read} →</a>`:''}</footer></div></article>`}
function render(filter='all'){const selected=data.map((item,index)=>({item,index})).filter(x=>filter==='all'||String(x.item.platform).toLowerCase()===filter);list.innerHTML=selected.length?selected.map(x=>card(x.item,x.index)).join(''):`<p class="wd282-empty">${T.empty}</p>`;list.querySelectorAll('[data-index]').forEach(x=>x.onclick=()=>openViewer(data[Number(x.dataset.index)]))}
tabs.forEach(tab=>tab.onclick=()=>{tabs.forEach(x=>x.classList.toggle('is-active',x===tab));render(tab.dataset.watchFilter)});
fetch('/content/videos.json',{headers:{Accept:'application/json'}}).then(r=>r.ok?r.json():Promise.reject()).then(j=>{data=(j.items||j.videos||[]).filter(x=>x.visible!==false).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));render()}).catch(()=>render());
})();